s=s.replace('if(!user||user.role!=="admin") return <div className="min-h-screen grid place-items-center bg-[#070a12] px-5"><div className="glass w-full max-w-md rounded-3xl p-8 text-center"><div className="mx-auto h-16 w-16 overflow-hidden rounded-2xl"><img src={BRAND} alt="THE NEXT MIND" className="h-full w-full object-cover"/></div><h1 className="font-display mt-6 text-2xl font-semibold">Admin access</h1><p className="mt-3 text-sm leading-6 text-slate-400">Sign in with your authorized Manus account to manage THE NEXT MIND registrations.</p><button onClick={()=>startLogin()} className="mt-7 w-full rounded-xl bg-yellow-300 px-4 py-3.5 font-semibold text-slate-950">Sign in securely</button><a href="/" className="mt-4 block text-sm text-slate-500 hover:text-white">Return to registration</a></div></div>;', 'if(!user||user.role!=="admin") return <div className="min-h-screen grid place-items-center bg-[#070a12] px-5"><div className="glass w-full max-w-md rounded-3xl p-8 text-center"><div className="mx-auto h-16 w-16 overflow-hidden rounded-2xl"><img src={BRAND} alt="THE NEXT MIND" className="h-full w-full object-cover"/></div><h1 className="font-display mt-6 text-2xl font-semibold">{inviteParams?.token?"Admin invitation":"Admin access"}</h1><p className="mt-3 text-sm leading-6 text-slate-400">{inviteParams?.token?"Sign in first, then activate this secure one-time invitation to join the admin panel.":"Sign in with your authorized Manus account to manage THE NEXT MIND registrations."}</p>{!user?<button onClick={()=>startLogin(location)} className="mt-7 w-full rounded-xl bg-yellow-300 px-4 py-3.5 font-semibold text-slate-950">Sign in securely</button>:<button onClick={()=>consumeInvite.mutate({token:inviteParams!.token})} disabled={consumeInvite.isPending} className="mt-7 w-full rounded-xl bg-yellow-300 px-4 py-3.5 font-semibold text-slate-950">{consumeInvite.isPending?"Activating…":"Activate admin access"}</button>}<a href="/" className="mt-4 block text-sm text-slate-500 hover:text-white">Return to registration</a></div></div>;')
